#include "log.h"

#include <windows.h>
#include <cstdio>

#include "messages.h" /* generated by mc.exe from messages.mc */
#include "service.h"
#include "util.h"

namespace {

CRITICAL_SECTION g_lock;
bool g_initialized = false;
std::wstring g_dir;
int g_retentionDays = 14;
bool g_console = false;
FILE* g_consoleInfo = stdout;
HANDLE g_eventSource = NULL;
HANDLE g_file = INVALID_HANDLE_VALUE;
std::wstring g_fileDate; /* YYYY-MM-DD of the open file */

std::wstring DateString(const SYSTEMTIME& st)
{
    wchar_t buf[16];
    _snwprintf_s(buf, _countof(buf), _TRUNCATE, L"%04u-%02u-%02u", st.wYear, st.wMonth, st.wDay);
    return buf;
}

void PurgeOldFiles(const SYSTEMTIME& now)
{
    if (g_retentionDays <= 0) return;
    FILETIME ft;
    SystemTimeToFileTime(&now, &ft);
    ULARGE_INTEGER u;
    u.LowPart = ft.dwLowDateTime;
    u.HighPart = ft.dwHighDateTime;
    u.QuadPart -= (ULONGLONG)g_retentionDays * 24ULL * 3600ULL * 10000000ULL;
    ft.dwLowDateTime = u.LowPart;
    ft.dwHighDateTime = u.HighPart;
    SYSTEMTIME cutoff;
    FileTimeToSystemTime(&ft, &cutoff);
    std::wstring cutoffName = L"vista-sync-" + DateString(cutoff) + L".log";

    WIN32_FIND_DATAW fd;
    HANDLE find = FindFirstFileW(JoinPath(g_dir, L"vista-sync-*.log").c_str(), &fd);
    if (find == INVALID_HANDLE_VALUE) return;
    do {
        std::wstring name = fd.cFileName;
        /* Names sort by date, so a plain string compare finds the old ones. */
        if (name.size() == cutoffName.size() && name < cutoffName)
            DeleteFileW(JoinPath(g_dir, name).c_str());
    } while (FindNextFileW(find, &fd));
    FindClose(find);
}

void OpenFileFor(const SYSTEMTIME& now)
{
    std::wstring date = DateString(now);
    if (g_file != INVALID_HANDLE_VALUE && date == g_fileDate) return;
    if (g_file != INVALID_HANDLE_VALUE) CloseHandle(g_file);
    g_file = INVALID_HANDLE_VALUE;
    if (g_dir.empty() || !EnsureDirectory(g_dir)) return;
    std::wstring path = JoinPath(g_dir, L"vista-sync-" + date + L".log");
    g_file = CreateFileW(path.c_str(), FILE_APPEND_DATA, FILE_SHARE_READ | FILE_SHARE_WRITE, NULL,
                         OPEN_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);
    g_fileDate = date;
    PurgeOldFiles(now);
}

const char* LevelName(Log::Level l)
{
    switch (l) {
    case Log::Debug: return "DEBUG";
    case Log::Info: return "INFO ";
    case Log::Notice: return "INFO ";
    case Log::Warning: return "WARN ";
    default: return "ERROR";
    }
}

}

namespace Log {

void Init(const std::wstring& dir, int retentionDays, bool eventLog, bool console)
{
    if (!g_initialized) {
        InitializeCriticalSection(&g_lock);
        g_initialized = true;
    }
    EnterCriticalSection(&g_lock);
    g_dir = dir;
    g_retentionDays = retentionDays;
    g_console = console;
    if (g_file != INVALID_HANDLE_VALUE) {
        CloseHandle(g_file);
        g_file = INVALID_HANDLE_VALUE;
    }
    if (eventLog && !g_eventSource) g_eventSource = RegisterEventSourceW(NULL, kServiceName);
    if (!eventLog && g_eventSource) {
        DeregisterEventSource(g_eventSource);
        g_eventSource = NULL;
    }
    LeaveCriticalSection(&g_lock);
}

void SetConsoleInfoStream(FILE* stream)
{
    g_consoleInfo = stream ? stream : stdout;
}

void Shutdown()
{
    if (!g_initialized) return;
    EnterCriticalSection(&g_lock);
    if (g_file != INVALID_HANDLE_VALUE) CloseHandle(g_file);
    g_file = INVALID_HANDLE_VALUE;
    if (g_eventSource) DeregisterEventSource(g_eventSource);
    g_eventSource = NULL;
    LeaveCriticalSection(&g_lock);
}

void Write(Level level, const char* fmt, ...)
{
    va_list args;
    va_start(args, fmt);
    std::string msg = FormatV(fmt, args);
    va_end(args);

    if (!g_initialized) {
        InitializeCriticalSection(&g_lock);
        g_initialized = true;
    }
    EnterCriticalSection(&g_lock);
    SYSTEMTIME now;
    GetLocalTime(&now);
    std::string line = Format("%04u-%02u-%02u %02u:%02u:%02u.%03u [%s] %s\r\n", now.wYear, now.wMonth, now.wDay,
                              now.wHour, now.wMinute, now.wSecond, now.wMilliseconds, LevelName(level), msg.c_str());

    OpenFileFor(now);
    if (g_file != INVALID_HANDLE_VALUE) {
        DWORD written;
        WriteFile(g_file, line.data(), (DWORD)line.size(), &written, NULL);
    }
    if (g_console && level != Debug) {
        /* Normal progress goes to stdout so PowerShell does not show it as a NativeCommandError;
         * only warnings and errors go to stderr. */
        FILE* out = level >= Warning ? stderr : g_consoleInfo;
        fputs(line.c_str() + 11, out); /* skip the date on the console */
        fflush(out);
    }
    if (g_eventSource && level >= Notice) {
        WORD type = EVENTLOG_INFORMATION_TYPE;
        DWORD id = MSG_INFO;
        if (level == Warning) {
            type = EVENTLOG_WARNING_TYPE;
            id = MSG_WARNING;
        } else if (level == Error) {
            type = EVENTLOG_ERROR_TYPE;
            id = MSG_ERROR;
        }
        std::wstring w = Utf8ToWide(msg);
        LPCWSTR strings[1] = { w.c_str() };
        ReportEventW(g_eventSource, type, 0, id, NULL, 1, 0, strings, NULL);
    }
    LeaveCriticalSection(&g_lock);
}

}
